<template>
  <div class="app-container dashboard">
    <div class="head"><div><small>VIZORA OPERATIONS</small><h2>运营数据概览</h2><p>实时掌握用户、充值与 AI 生成任务表现</p></div><el-radio-group v-model="period"><el-radio-button label="day">日</el-radio-button><el-radio-button label="month">月</el-radio-button><el-radio-button label="year">年</el-radio-button></el-radio-group></div>
    <el-row :gutter="16" class="stats-row"><el-col v-for="s in stats" :key="s.name" :xs="24" :sm="12" :lg="6"><el-card shadow="never"><span class="label">{{ s.name }}</span><strong>{{ s.value }}</strong><em>↑ {{ s.rate }}{{ s.rate === '实时' ? '' : '% 较上期' }}</em></el-card></el-col></el-row>
    <el-row :gutter="16" class="charts"><el-col :xs="24" :lg="16"><el-card shadow="never"><template #header>核心指标趋势 <span>近{{ periodText }}</span></template><div class="bars"><i v-for="(v,i) in bars" :key="i" :style="{height:v+'%'}"><b>{{ labels[i] }}</b></i></div></el-card></el-col><el-col :xs="24" :lg="8"><el-card shadow="never"><template #header>任务结果分布</template><div class="donut"><div><strong>{{ successRate }}%</strong><span>成功率</span></div></div><div class="legend"><span>● 成功 {{ successRate }}%</span><span>● 失败 {{ failedRate }}%</span><span>● 处理中 {{ processingRate }}%</span></div></el-card></el-col></el-row>
    <el-row :gutter="16"><el-col :xs="24" :lg="16"><el-card shadow="never"><template #header>充值概览</template><div class="mini"><div>充值订单<strong>{{ total('orders') }}</strong></div><div>充值金额<strong>¥{{ total('amount').toLocaleString() }}</strong></div><div>客单价<strong>¥{{ averageOrder }}</strong></div></div></el-card></el-col><el-col :xs="24" :lg="8"><el-card shadow="never"><template #header>算力消耗</template><div class="progress"><el-progress :percentage="creditPercent" color="#b9ef45" :stroke-width="18"/><p>本期消耗 {{ total('credits').toLocaleString() }} 点</p></div></el-card></el-col></el-row>
  </div>
</template>
<script setup name="Index">
import { getDashboardStats } from '@/api/vizora/operation'
const period=ref('day'), rows=ref([]), periodText=computed(()=>({day:'7日',month:'6个月',year:'5年'}[period.value]))
const labels=computed(()=>rows.value.map(r=>r.bucket)), bars=computed(()=>{const max=Math.max(...rows.value.map(r=>Number(r.tasks)||0),1);return rows.value.map(r=>Math.max(8,Math.round(Number(r.tasks||0)/max*100)))})
const total=(key)=>rows.value.reduce((n,r)=>n+Number(r[key]||0),0)
const stats=computed(()=>[{name:'新增用户',value:total('users').toLocaleString(),rate:'实时'},{name:'充值金额',value:`¥${total('amount').toLocaleString()}`,rate:'实时'},{name:'生成任务',value:total('tasks').toLocaleString(),rate:'实时'},{name:'算力消耗',value:`${total('credits').toLocaleString()} 点`,rate:'实时'}])
const successRate=computed(()=>percent(total('success'))), failedRate=computed(()=>percent(total('failed'))), processingRate=computed(()=>Math.max(0,100-Number(successRate.value)-Number(failedRate.value)))
function percent(v){const t=total('tasks');return t?((v/t)*100).toFixed(1):'0.0'}
const averageOrder=computed(()=>{const n=total('orders');return n?(total('amount')/n).toFixed(2):'0.00'}), creditPercent=computed(()=>Math.min(100,Math.round(total('credits')/Math.max(total('credits'),1)*100)))
async function load(){const res=await getDashboardStats(period.value);rows.value=res.data||[]} watch(period,load); load()
</script>
<style scoped>
.dashboard{background:#f7f8f4;min-height:calc(100vh - 84px)}.head{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.head small{color:#7a9c38;letter-spacing:2px}.head h2{margin:7px 0 4px;color:#263026}.head p{margin:0;color:#849087}.el-card{margin-bottom:16px;border:1px solid #e6eadf;border-radius:12px}.label{display:block;color:#7b857d}.el-card strong{display:block;font-size:27px;color:#202722;margin:10px 0}.el-card em{font-style:normal;color:#6b9d28;font-size:13px}.charts{margin-top:16px}.el-card :deep(.el-card__header){font-weight:600;color:#273029}.el-card :deep(.el-card__header) span{float:right;color:#98a095;font-size:13px;font-weight:400}.bars{height:260px;display:flex;align-items:end;gap:7%;padding:20px 5% 25px}.bars i{flex:1;background:linear-gradient(#b9ef45,#8fcf32);border-radius:6px 6px 0 0;position:relative}.bars b{position:absolute;bottom:-22px;left:50%;transform:translateX(-50%);font-size:12px;color:#8c978d;font-weight:400}.donut{width:170px;height:170px;margin:20px auto;border-radius:50%;background:conic-gradient(#9bdc3c 0 78%,#f56c6c 78% 92%,#4d8dff 92%);display:grid;place-items:center}.donut div{width:110px;height:110px;background:white;border-radius:50%;display:grid;place-items:center;align-content:center}.donut strong{font-size:25px;margin:0}.donut span{font-size:12px;color:#8c978d}.legend{display:flex;justify-content:space-around;color:#7c877d;font-size:12px}.legend span:first-child{color:#7aa934}.mini{display:flex;justify-content:space-around;padding:14px 0;color:#89938a}.mini strong{font-size:21px;margin-top:8px}.progress{padding:20px 10px}.progress p{color:#89938a;font-size:13px}
</style>
<style scoped>.stats-row{display:flex;align-items:stretch}.stats-row>.el-col{display:flex}.stats-row .el-card{width:100%;height:150px}</style>
